"""The assembler's opcode table, on the host. src/bin/as_ops.inc is generated by tools/gen_as_ops.py
(OPS); this checks the committed table against OPS, and assembles every legal (mnemonic, mode) pair
with `as` under py65 (tools/asim.py): each must come out as its opcode and operand bytes."""
import importlib.util
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import asim  # noqa: E402

ROOT = asim.ROOT
spec = importlib.util.spec_from_file_location("gen_as_ops", os.path.join(HERE, "gen_as_ops.py"))
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)
OPS, MODES = gen.OPS, gen.M

# operand source per mode, and the operand bytes it must assemble to
MODE_SRC = {
    "imp": ("{n}", b""), "acc": ("{n} a", b""), "imm": ("{n} #$5a", b"\x5a"),
    "zp": ("{n} $12", b"\x12"), "zpx": ("{n} $12,x", b"\x12"), "zpy": ("{n} $12,y", b"\x12"),
    "abs": ("{n} $1234", b"\x34\x12"), "absx": ("{n} $1234,x", b"\x34\x12"),
    "absy": ("{n} $1234,y", b"\x34\x12"), "indx": ("{n} ($12,x)", b"\x12"),
    "indy": ("{n} ($12),y", b"\x12"), "ind": ("{n} ($1234)", b"\x34\x12"),
    "rel": ("{n} t{i}\nt{i}:", b"\x00"),          # a branch to the next byte: offset 0
}
MODE_SRC_CHECK = set(MODE_SRC) == set(MODES)


def legal_pairs():
    return [(n, m) for n in sorted(OPS) for m in MODES if m in OPS[n]]


def committed_table():
    """(text, names, rows) from src/bin/as_ops.inc: the names in order, and each mnemonic's row of 13
    entries (0xff where the mode is not legal). A record is: count, mask lo, mask hi, the legal opcodes."""
    with open(os.path.join(ROOT, "src", "bin", "as_ops.inc")) as f:
        text = f.read()
    names = re.findall(r'^\s*\.byte "([a-z]{3})"$', text, re.M)
    rows = {}
    for m in re.finditer(r"^\s*\.byte (\d+), \$([0-9a-f]{2}), \$([0-9a-f]{2})((?:, \$[0-9a-f]{2})*)\s*; ([a-z]{3})$",
                         text, re.M):
        count, lo, hi = int(m.group(1)), int(m.group(2), 16), int(m.group(3), 16)
        ops = [int(v[1:], 16) for v in m.group(4).split(", ") if v]
        mask = lo | (hi << 8)
        assert count == len(ops) == bin(mask).count("1"), m.group(5)
        row, k = [], 0
        for mode in range(13):
            if mask >> mode & 1:
                row.append(ops[k])
                k += 1
            else:
                row.append(0xFF)
        rows[m.group(5)] = row
    return text, names, rows


class OpcodeTable(unittest.TestCase):
    def test_committed_table_is_the_generator_output(self):
        text, _, _ = committed_table()
        self.assertEqual(text, gen.render(), "src/bin/as_ops.inc is stale: run python3 tools/gen_as_ops.py")

    def test_names_and_rows_match_ops(self):
        _, names, rows = committed_table()
        self.assertEqual(names, sorted(OPS))
        self.assertEqual(len(names), 56)
        self.assertEqual(len(rows), 56)
        for n in OPS:
            self.assertEqual(rows[n], [OPS[n].get(m, 0xFF) for m in MODES], n)

    def test_every_mode_has_source_syntax(self):
        self.assertTrue(MODE_SRC_CHECK, "MODE_SRC and the generator's modes differ")

    def test_count_of_legal_pairs(self):
        # the generator's OPS: 56 mnemonics, 151 legal (mnemonic, mode) pairs
        self.assertEqual(len(legal_pairs()), 151)


@unittest.skipIf(asim.MPU is None, "py65 not installed")
@unittest.skipIf(not os.path.exists(os.path.join(ROOT, "build", "root", "bin", "as")), "not built (make)")
class EveryLegalPair(unittest.TestCase):
    def test_every_legal_pair_assembles_to_its_opcode(self):
        pairs = legal_pairs()
        lines, want = [], b""
        for i, (n, m) in enumerate(pairs):
            src, operand = MODE_SRC[m]
            lines.append(src.format(n=n, i=i))
            want += bytes([OPS[n][m]]) + operand
        src = "\n".join(lines) + "\n"
        r = asim.run("as", ["/s", "/o"], {"/s": src.encode()})
        self.assertEqual(r.exit, 0, (r.out, r.err))
        b = r.files["/o"]
        self.assertEqual(b[:3], b"CX\x01")
        image = int.from_bytes(b[3:5], "little")
        got = b[9:9 + image]
        self.assertEqual(len(got), len(want), "image size: %d, expected %d" % (len(got), len(want)))
        for k, (n, m) in enumerate(pairs):
            start = sum(len(bytes([OPS[x][y]])) + len(MODE_SRC[y][1]) for x, y in pairs[:k])
            size = 1 + len(MODE_SRC[m][1])
            self.assertEqual(got[start:start + size], want[start:start + size], "%s %s" % (n, m))
        print("\nassembled and checked %d legal (mnemonic, mode) pairs" % len(pairs))


if __name__ == "__main__":
    unittest.main()
